package org.autotest;

import java.io.IOException;

import org.autotest.controller.TestController;
import org.autotest.model.Test;
import org.autotest.repository.SerializarPreguntas;

import javafx.application.Application;
import javafx.application.Platform;
import javafx.fxml.FXMLLoader;
import javafx.scene.Scene;
import javafx.scene.input.KeyCode;
import javafx.scene.input.KeyCombination;
import javafx.stage.Stage;

public class App extends Application {

    @Override
    public void start(Stage stage) throws IOException {
        Test test = new SerializarPreguntas().cargarTest("/data/preguntas.json");

        FXMLLoader loader = new FXMLLoader(getClass().getResource("/ui/test.fxml"));
        Scene scene = new Scene(loader.load());
        scene.getStylesheets().add(getClass().getResource("/css/test.css").toExternalForm());
        scene.getStylesheets().add(getClass().getResource("/css/questions.css").toExternalForm());
        TestController controller = loader.getController();
        controller.setPreguntas(test.getPreguntas());

        stage.setTitle("Test diseño de interfaces");
        stage.setScene(scene);
        stage.setFullScreenExitKeyCombination(KeyCombination.NO_MATCH);
        scene.addEventFilter(javafx.scene.input.KeyEvent.KEY_PRESSED, event -> {
            if (event.getCode() == KeyCode.F11) {
                stage.setFullScreen(!stage.isFullScreen());
                event.consume();
            } else if (event.getCode() == KeyCode.ESCAPE) {
                stage.close();
                event.consume();
            }
        });
        stage.show();
        stage.setFullScreen(true);
        stage.requestFocus();
        Platform.runLater(() -> {
            stage.requestFocus();
            scene.getRoot().requestFocus();
        });
    }

    public static void main(String[] args) {
        launch(args);
    }
}
